
import java.io.ObjectInputStream;
import java.io.ObjectOutputStream;
import java.io.ByteArrayOutputStream;
import java.net.Socket;
import java.nio.charset.StandardCharsets;
import java.math.BigInteger; 
import static java.lang.Math.*; 
import java.util.Scanner; 
/**
 * A password manager client.
 * You will need to give it an interface with the options to send the server a password to store, to
 * get a stored password from the server, and to end the programs. You will also have to implement RSA
 * and use it correctly so that the server and any possible interceptor can never read the passwords.
 */
public class Client {

    /**
     * Send and receive a message in bytes to the specified host at the specified port.
     * 
     * @param host string stating the name or ip address of the server
     * @param port int stating the port number of the server
     * @param message byte array containing the message to send to the server
     * @return a byte array containing the message that is received back from the server
     */

     static String hostname = "localhost"; 
     static int port = 22500; 

    public static byte[] sendReceive(String hostname, int port, byte[] message) {
        try (
            Socket s = new Socket(hostname, port);
        ) {
            ObjectOutputStream out = new ObjectOutputStream(s.getOutputStream());
            out.writeObject(message);  // Send the message to the server
            out.flush();
            ObjectInputStream in = new ObjectInputStream(s.getInputStream());
            byte buffer[] = (byte[]) in.readObject(); // Receive a message from the server
           

            return buffer;
            //return (byte[])in.readObject();
        } catch (Exception e) {
            e.printStackTrace();
        }
        return null;
    }


    public static void main(String[] args) {
       
        menu();
        
    }

    static BigInteger encrypt(String message){

        BigInteger p = new BigInteger("");
        BigInteger q = new BigInteger("");
        BigInteger n = p.multiply(q);
        BigInteger pdiff = new BigInteger("");
        BigInteger qdiff = new BigInteger("");

        BigInteger phi_n = pdiff.multiply(qdiff);
        BigInteger e = new BigInteger("5475"); 
        int eint = 5475; 
       
        BigInteger d = e.modInverse(phi_n);  
        
        byte[] messageBytes = message.getBytes(); 
        BigInteger m = new BigInteger(1, messageBytes);
        BigInteger ciphertext = powmod(m, e, n);
        return ciphertext; 

    }


    static String decrypt(BigInteger ciphertext){
        BigInteger p = new BigInteger("");
        BigInteger q = new BigInteger("");
        BigInteger n = p.multiply(q);
        BigInteger pdiff = new BigInteger("");
        BigInteger qdiff = new BigInteger("");

        BigInteger phi_n = pdiff.multiply(qdiff);
        BigInteger e = new BigInteger("5475"); 
        int eint = 5475; 
       
        BigInteger d = e.modInverse(phi_n); 
        BigInteger plaintext = powmod(ciphertext, d, n);
        byte[] bytes = plaintext.toByteArray(); 
        return new String(bytes); 
    }

    static BigInteger powmod(BigInteger b, BigInteger e, BigInteger m) {
        BigInteger result = BigInteger.ONE; 
        BigInteger base = b.mod(m);
        BigInteger exp = e; 
        
        while(exp.signum() > 0){
            if(exp.testBit(0)){
                result = result.multiply(base).mod(m);
            }
            base = base.multiply(base).mod(m);
            exp = exp.shiftRight(1);
        }
        return result; 
    }

    static void menu(){
        Scanner sc = new Scanner(System.in); 
        
        String input = "";

        System.out.println("Welcome to the Seng2250 password manager client,");
        while(!input.equalsIgnoreCase("end")){
            System.out.println("\nyou have the following options:\r\n" + //
                        "- store <website> <password>\r\n" + //
                        "- get <website>\r\n" + //
                        "- end");
                        input = sc.nextLine();
                        String[] split = input.split("\\s+",3 ); 
                        
                if(split[0].equalsIgnoreCase("store")){
                    
                    
                    String website = split[1]; 
                    String password = split[2]; 
                   
                    BigInteger ciphertext1 = encrypt(password); 
                    
                    String String2 ="store " +website; 
                    String concatenate = String2 + " " +ciphertext1; 
                    byte[] byteArray = concatenate.getBytes();
                    String response = new String(sendReceive(hostname, port, byteArray), StandardCharsets.UTF_8);
                    System.out.println(response);
                }

                else if(split[0].equalsIgnoreCase("get")){
                    byte[] byteArray = input.getBytes(); 
                    byte[] response = sendReceive(hostname, port, byteArray);
                    String reply = new String(response);
                    BigInteger ciphertext = new BigInteger(reply);
                    String plaintext = decrypt(ciphertext);
                    System.out.println(plaintext);
                    

                }

                else if(split[0].equalsIgnoreCase("end")){
                   byte[] byteArray = input.getBytes();
                    String response = new String(sendReceive(hostname, port, byteArray), StandardCharsets.UTF_8);
                    System.out.println(response);
                    System.exit(0);
                }
        }
    }

}
